class Solution {
    public: int sumSubseqWidths(vector<int>& nums){
        sort(nums.begin(),nums.end());
        const long long mod=1000000007;
        vector<long long> powers(nums.size());
        powers[0]=1;
        for(int i=1;i<(int)nums.size();++i)powers[i]=powers[i-1]*2%mod;
        long long answer=0;
        for(int i=0;i<(int)nums.size();++i)answer=(answer+nums[i]*(powers[i]-powers[nums.size()-1-i]))%mod;
        return(answer+mod)%mod;
    }
};
